"""Rebuild firmware/gas_monitor/page.h from firmware/local_page.html (the page served at http://gas.local).
Run from the repo root after editing the local page:  python tools/build_page.py"""
from pathlib import Path

root = Path(__file__).resolve().parent.parent
page = (root / "firmware" / "local_page.html").read_text(encoding="utf-8")
assert ')rawliteral"' not in page, "page contains the raw-string terminator"
out = root / "firmware" / "gas_monitor" / "page.h"
out.write_text(
    "// GENERATED by tools/build_page.py from firmware/local_page.html. Edit that file, not this one.\n"
    "#pragma once\n"
    'const char PAGE[] = R"rawliteral(' + page + ')rawliteral";\n',
    encoding="utf-8", newline="\n")
print("wrote", out)
